import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as d,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"Kimi Code cheatsheet","description":"Lookup only. Commands, flags, slash commands, model IDs, and Base URLs are copied from official docs. The full set is always kimi --help plus moonshotai.github.io/kimi-code.","frontmatter":{"title":"Kimi Code cheatsheet","description":"Lookup only. Commands, flags, slash commands, model IDs, and Base URLs are copied from official docs. The full set is always kimi --help plus moonshotai.github.io/kimi-code.","domain":"product","tags":["coding-agent"],"role":"cheatsheet"},"headers":[],"relativePath":"products/kimi-code/kimi-code-cheatsheet.md","filePath":"products/kimi-code/kimi-code-cheatsheet.md","lastUpdated":1787107158000}'),i={name:"products/kimi-code/kimi-code-cheatsheet.md"};function a(c,t,s,l,n,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="kimi-code-cheatsheet" tabindex="-1">Kimi Code cheatsheet <a class="header-anchor" href="#kimi-code-cheatsheet" aria-label="Permalink to &quot;Kimi Code cheatsheet&quot;">​</a></h1><p>Lookup only. CLI: <a href="https://moonshotai.github.io/kimi-code/en/reference/kimi-command" target="_blank" rel="noreferrer">kimi command</a> and <code>kimi --help</code>. Models / membership: <a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">models</a> and <a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">membership</a>.</p><p>Covers official pages opened on 2026-08-19. npm <code>@moonshot-ai/kimi-code</code> <code>latest</code> that day was <code>0.37.1</code>. Run <code>kimi --version</code> and check the <a href="https://moonshotai.github.io/kimi-code/en/release-notes/changelog" target="_blank" rel="noreferrer">changelog</a>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Command</th></tr></thead><tbody><tr><td>macOS / Linux (recommended)</td><td><code>curl -fsSL https://code.kimi.com/kimi-code/install.sh | bash</code></td></tr><tr><td>Windows PowerShell</td><td><code>irm https://code.kimi.com/kimi-code/install.ps1 | iex</code></td></tr><tr><td>npm (Node <strong>≥ 22.19.0</strong>)</td><td><code>npm install -g @moonshot-ai/kimi-code</code></td></tr><tr><td>pnpm</td><td><code>pnpm add -g @moonshot-ai/kimi-code</code></td></tr><tr><td>Version</td><td><code>kimi --version</code> (<code>-V</code>)</td></tr><tr><td>Upgrade</td><td><code>kimi upgrade</code> (alias <code>kimi update</code>)</td></tr><tr><td>npm upgrade</td><td><code>npm install -g @moonshot-ai/kimi-code@latest</code></td></tr><tr><td>Homebrew upgrade</td><td><code>brew upgrade kimi-code</code> (What&#39;s New; Getting Started has no install text)</td></tr><tr><td>npm uninstall</td><td><code>npm uninstall -g @moonshot-ai/kimi-code</code></td></tr></tbody></table><p>Windows: install Git for Windows first; custom Git Bash path → <code>KIMI_SHELL_PATH</code>.</p><p>Old <code>https://code.kimi.com/install.sh</code> (no <code>kimi-code/</code>) and <code>uv tool install … kimi-cli</code> are the Python line. Do not use them.</p><h2 id="main-flags" tabindex="-1">Main flags <a class="header-anchor" href="#main-flags" aria-label="Permalink to &quot;Main flags&quot;">​</a></h2><p>Source: <a href="https://moonshotai.github.io/kimi-code/en/reference/kimi-command" target="_blank" rel="noreferrer">kimi command</a></p><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--version</code></td><td><code>-V</code></td><td>Print version</td></tr><tr><td><code>--help</code></td><td><code>-h</code></td><td>Help</td></tr><tr><td><code>--session [id]</code></td><td><code>-S</code></td><td>Resume; omit ID for a picker. Hidden alias <code>-r</code> / <code>--resume</code></td></tr><tr><td><code>--continue</code></td><td><code>-c</code></td><td>Resume latest session in this directory</td></tr><tr><td><code>--model &lt;model&gt;</code></td><td><code>-m</code></td><td>Model alias for this launch</td></tr><tr><td><code>--prompt &lt;prompt&gt;</code></td><td><code>-p</code></td><td>One-shot, no TUI</td></tr><tr><td><code>--output-format &lt;format&gt;</code></td><td></td><td><code>text</code> or <code>stream-json</code>; only with <code>-p</code></td></tr><tr><td><code>--yolo</code></td><td><code>-y</code></td><td>Auto-approve ordinary tools. Hidden aliases <code>--yes</code>, <code>--auto-approve</code></td></tr><tr><td><code>--auto</code></td><td></td><td>Auto permission; no questions</td></tr><tr><td><code>--plan</code></td><td></td><td>Start in Plan mode</td></tr><tr><td><code>--skills-dir &lt;dir&gt;</code></td><td></td><td>Replace auto-discovered Skills dirs; repeatable</td></tr><tr><td><code>--agent &lt;name&gt;</code></td><td></td><td>Main agent (not with <code>--session</code>/<code>--continue</code>)</td></tr><tr><td><code>--agent-file &lt;path&gt;</code></td><td></td><td>Load an agent from Markdown</td></tr><tr><td><code>--add-dir &lt;dir&gt;</code></td><td></td><td>Extra workdir; repeatable</td></tr></tbody></table><p>Conflicts: <code>--continue</code> × <code>--session</code>; <code>--yolo</code> × <code>--auto</code>; <code>-p</code> cannot combine with <code>--yolo</code> / <code>--auto</code> / <code>--plan</code>. <code>-p</code> is locked to <code>auto</code> permission.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Role</th></tr></thead><tbody><tr><td><code>kimi</code></td><td>No args: new TUI session here</td></tr><tr><td><code>kimi login</code></td><td>Non-interactive OAuth device-code</td></tr><tr><td><code>kimi acp</code></td><td>ACP stdio for IDEs</td></tr><tr><td><code>kimi web</code></td><td>Foreground REST/WS + web UI. Default port <code>58627</code></td></tr><tr><td><code>kimi doctor</code></td><td>Validate <code>config.toml</code> / <code>tui.toml</code></td></tr><tr><td><code>kimi export [sessionId]</code></td><td>Zip a session</td></tr><tr><td><code>kimi migrate</code></td><td>Import old <code>kimi-cli</code> data</td></tr><tr><td><code>kimi upgrade</code></td><td>Check and install updates</td></tr><tr><td><code>kimi vis [sessionId]</code></td><td>Visualize a session in the browser</td></tr><tr><td><code>kimi provider …</code></td><td>Non-interactive provider admin</td></tr></tbody></table><p><code>kimi server …</code> is deprecated (exit 1). Use <code>kimi web</code>. Exception: <code>kimi server kill</code> only stops pre-0.28.0 background servers.</p><h2 id="slash-commands-starter-set" tabindex="-1">Slash commands (starter set) <a class="header-anchor" href="#slash-commands-starter-set" aria-label="Permalink to &quot;Slash commands (starter set)&quot;">​</a></h2><p>Full list: <a href="https://moonshotai.github.io/kimi-code/en/reference/slash-commands" target="_blank" rel="noreferrer">slash-commands</a></p><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Role</th></tr></thead><tbody><tr><td><code>/login</code></td><td></td><td>OAuth or Platform key</td></tr><tr><td><code>/logout</code></td><td></td><td>Clear current credentials</td></tr><tr><td><code>/model</code></td><td></td><td>Switch model</td></tr><tr><td><code>/provider</code></td><td></td><td>Provider manager</td></tr><tr><td><code>/new</code></td><td><code>/clear</code></td><td>New session</td></tr><tr><td><code>/sessions</code></td><td><code>/resume</code></td><td>Resume history</td></tr><tr><td><code>/fork</code></td><td></td><td>Fork a copy</td></tr><tr><td><code>/compact [hint]</code></td><td></td><td>Compress context</td></tr><tr><td><code>/init</code></td><td></td><td>Write <code>AGENTS.md</code></td></tr><tr><td><code>/usage</code></td><td></td><td>Usage / quota</td></tr><tr><td><code>/status</code></td><td></td><td>Runtime status</td></tr><tr><td><code>/yolo [on|off]</code></td><td><code>/yes</code></td><td>YOLO</td></tr><tr><td><code>/auto [on|off]</code></td><td></td><td>Auto</td></tr><tr><td><code>/plan [on|off]</code></td><td></td><td>Plan</td></tr><tr><td><code>/goal …</code></td><td></td><td>Goal mode</td></tr><tr><td><code>/swarm &lt;task&gt;</code></td><td></td><td>Multi-agent parallel</td></tr><tr><td><code>/btw [question]</code></td><td></td><td>Side-channel subagent</td></tr><tr><td><code>/mcp</code></td><td></td><td>MCP status</td></tr><tr><td><code>/mcp-config</code></td><td></td><td>Configure MCP (built-in skill)</td></tr><tr><td><code>/help</code></td><td><code>/h</code> <code>/?</code></td><td>Help</td></tr><tr><td><code>/exit</code></td><td><code>/quit</code> <code>/q</code></td><td>Quit</td></tr></tbody></table><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Send</td></tr><tr><td><code>Shift-Enter</code> / <code>Ctrl-J</code></td><td>Newline</td></tr><tr><td><code>Esc</code></td><td>Interrupt / close popup</td></tr><tr><td><code>Ctrl-C</code></td><td>Interrupt; twice while idle exits</td></tr><tr><td><code>Ctrl-D</code></td><td>Exit when the input is empty</td></tr><tr><td><code>Shift-Tab</code></td><td>Toggle Plan</td></tr><tr><td><code>Ctrl-S</code></td><td>Interject while streaming</td></tr><tr><td><code>Ctrl-O</code></td><td>Collapse tool output</td></tr><tr><td><code>Ctrl-G</code></td><td>External editor</td></tr><tr><td><code>!</code> (empty input)</td><td>Shell mode</td></tr><tr><td><code>@</code></td><td>File mention</td></tr><tr><td><code>/</code></td><td>Slash command</td></tr></tbody></table><p>Paste media: <code>Ctrl-V</code> on macOS/Linux, <code>Alt-V</code> on Windows.</p><h2 id="vs-code-extension" tabindex="-1">VS Code extension <a class="header-anchor" href="#vs-code-extension" aria-label="Permalink to &quot;VS Code extension&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Marketplace</td><td><a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">moonshot-ai.kimi-code</a></td></tr><tr><td>Search</td><td><code>Kimi Code</code>, publisher <code>moonshot-ai</code></td></tr><tr><td>Eligibility</td><td>Product docs: new installs only for legacy Python CLI users</td></tr><tr><td>VS Code version (Marketplace)</td><td><code>&gt;= 1.100.0</code></td></tr><tr><td>Focus input</td><td><code>Ctrl+Shift+K</code> / <code>Cmd+Shift+K</code></td></tr><tr><td>Insert current file</td><td><code>Alt+K</code></td></tr><tr><td>New conversation</td><td><code>Ctrl+N</code> / <code>Cmd+N</code> (needs <code>kimi.enableNewConversationShortcut</code>)</td></tr></tbody></table><h2 id="model-ids" tabindex="-1">Model IDs <a class="header-anchor" href="#model-ids" aria-label="Permalink to &quot;Model IDs&quot;">​</a></h2><p>Source: <a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">Models</a> (3 IDs)</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Model</th><th>Context</th><th>Plan</th></tr></thead><tbody><tr><td><code>k3</code></td><td>Kimi K3</td><td>Moderato 256k; Allegretto+ up to 1M</td><td>Moderato+ (Andante not yet)</td></tr><tr><td><code>kimi-for-coding</code></td><td>K2.7 Code</td><td>256k</td><td>All members</td></tr><tr><td><code>kimi-for-coding-highspeed</code></td><td>Same, high speed</td><td>256k</td><td>Allegretto+</td></tr></tbody></table><p>A wrong high-speed ID silently falls back to the standard ID. Unauthorized → <code>401</code>. Third-party 1M windows: set context to <code>1048576</code>.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Kimi Code</th><th>Open Platform</th></tr></thead><tbody><tr><td>OpenAI Base URL</td><td><code>https://api.kimi.com/coding/v1</code></td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>Anthropic Base URL</td><td><code>https://api.kimi.com/coding/</code></td><td>—</td></tr><tr><td>Billing</td><td>membership + rate limits</td><td>metered</td></tr><tr><td>Create key</td><td><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">console</a> (max 5, shown once)</td><td>Open Platform console</td></tr></tbody></table><p>Keys do not mix. Do not rewrite the User-Agent.</p><h2 id="paths-and-env" tabindex="-1">Paths and env <a class="header-anchor" href="#paths-and-env" aria-label="Permalink to &quot;Paths and env&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key / path</th><th>Role</th></tr></thead><tbody><tr><td><code>~/.kimi-code/</code></td><td>Current data root</td></tr><tr><td><code>~/.kimi-code/config.toml</code></td><td>Agent / permissions / providers</td></tr><tr><td><code>~/.kimi-code/tui.toml</code></td><td>Theme, editor, notifications, auto-update</td></tr><tr><td><code>~/.kimi/</code></td><td><strong>Legacy</strong> Python CLI</td></tr><tr><td><code>KIMI_CODE_HOME</code></td><td>Override data root</td></tr><tr><td><code>KIMI_SHELL_PATH</code></td><td>Windows <code>bash.exe</code></td></tr><tr><td><code>KIMI_DISABLE_TELEMETRY=1</code></td><td>Disable anonymous telemetry (<code>true</code>/<code>yes</code>/<code>y</code> also work)</td></tr></tbody></table><p><code>KIMI_API_KEY</code> is <strong>not</strong> read from the shell.</p><h2 id="permission-modes" tabindex="-1">Permission modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>CLI</th><th>TUI</th><th>Behavior</th></tr></thead><tbody><tr><td>Default manual</td><td>(no flag)</td><td></td><td>Writes / shell ask first</td></tr><tr><td>Plan</td><td><code>--plan</code></td><td><code>Shift-Tab</code> <code>/plan</code></td><td>Plan first; leaving Plan still asks (even under YOLO)</td></tr><tr><td>YOLO</td><td><code>--yolo</code> <code>-y</code></td><td><code>/yolo</code></td><td>Auto-approve ordinary tools</td></tr><tr><td>Auto</td><td><code>--auto</code></td><td><code>/auto</code></td><td>Fully automatic, no questions</td></tr><tr><td><code>-p</code></td><td>locked to auto</td><td>—</td><td>Cannot stack yolo/auto/plan</td></tr></tbody></table><h2 id="high-quality-sources" tabindex="-1">High-quality sources <a class="header-anchor" href="#high-quality-sources" aria-label="Permalink to &quot;High-quality sources&quot;">​</a></h2><ul><li><strong><a href="https://www.kimi.com/code" target="_blank" rel="noreferrer">Kimi Code landing</a></strong> — current curl install bar <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">Product docs hub</a></strong> — membership, VS Code, API, models <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://moonshotai.github.io/kimi-code/en/" target="_blank" rel="noreferrer">CLI docs (EN)</a></strong> / <strong><a href="https://moonshotai.github.io/kimi-code/zh/" target="_blank" rel="noreferrer">ZH</a></strong> — Guides + Reference <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">Models</a></strong> — three Model IDs and plan gates <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">Membership</a></strong> — 7-day / 5-hour, Extra Usage <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New</a></strong> — rewrite table, feature drops <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">Product comparison</a></strong> — Kimi / Work / Code / Claw <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">GitHub MoonshotAI/kimi-code</a></strong> — README, source, Issues <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.npmjs.com/package/@moonshot-ai/kimi-code" target="_blank" rel="noreferrer">npm @moonshot-ai/kimi-code</a></strong> — version and <code>engines</code><ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">VS Marketplace moonshot-ai.kimi-code</a></strong> — extension implementation notes <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">Console</a></strong> — keys and quota <ul><li>Last verified: 2026-08-19</li></ul></li><li><strong><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">Open Platform</a></strong> — metered API, not the Code pool <ul><li>Last verified: 2026-08-19</li></ul></li></ul><h3 id="unverified" tabindex="-1">Unverified <a class="header-anchor" href="#unverified" aria-label="Permalink to &quot;Unverified&quot;">​</a></h3><ul><li>Whether the product hub still shows a fourth model ID <code>k3-256k</code> (conflicted with the models page on 2026-08-19)</li><li>Official <code>brew install</code> text (only <code>brew upgrade kimi-code</code> is documented)</li><li>A dedicated Kimi Claw landing URL (the comparison page names the product, not a separate host)</li></ul>',38)])])}const f=e(i,[["render",a]]);export{g as __pageData,f as default};
